def transform(grid):
    n, m = len(grid), len(grid[0])
    colors = max(max(row) for row in grid)
    start = next(v for v in grid[1] if v != 0)

    def seq(i):
        return (start - 1 + i) % colors + 1

    out = []
    for r in range(n):
        row = []
        if r == 0:
            first = (start - 2) % colors + 1
            row = [(first - 1 + c) % colors + 1 for c in range(m)]
        else:
            for c in range(m):
                if c < r:
                    row.append(seq(c))
                elif c == r:
                    row.append(seq(r - 1))
                else:
                    row.append(seq(c - 1))
        out.append(row)
    return out
